import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{o as e,c as l,d as a}from"./app-5d62b1ab.js";const s={},n=a(`<h1 id="编辑游戏配置" tabindex="-1"><a class="header-anchor" href="#编辑游戏配置" aria-hidden="true">#</a> 编辑游戏配置</h1><p>在 <code>game</code> 文件夹下，有一个名为 <code>config.txt</code> 的文件，你可以在这个文件中填写你游戏的相关信息（使用图形化编辑器可以直接编辑）。</p><table><thead><tr><th style="text-align:left;">参数</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;">Game_name</td><td style="text-align:left;">游戏名称</td></tr><tr><td style="text-align:left;">Game_key</td><td style="text-align:left;">游戏识别码，长度 6-10 字符，不要与别的游戏重复</td></tr><tr><td style="text-align:left;">Title_img</td><td style="text-align:left;">标题图片，放在 <code>background</code> 文件夹</td></tr><tr><td style="text-align:left;">Title_bgm</td><td style="text-align:left;">标题背景音乐，放在 <code>bgm</code> 文件夹</td></tr><tr><td style="text-align:left;">Game_Logo</td><td style="text-align:left;">游戏 Logo，可以显示多个，用 | 分割</td></tr><tr><td style="text-align:left;">Enable_Appreciation</td><td style="text-align:left;">是否启用鉴赏功能，包括 CG 和背景音乐鉴赏。</td></tr><tr><td style="text-align:left;">Default_Language</td><td style="text-align:left;">默认语言，可设置为 &#39;zh_CN&#39;, &#39;zh_TW&#39;, &#39;en&#39;, &#39;ja&#39;, &#39;fr&#39;, &#39;de&#39;</td></tr><tr><td style="text-align:left;">Show_panic</td><td style="text-align:left;">是否启用紧急回避功能，设置为 true 或 false</td></tr><tr><td style="text-align:left;">Legacy_Expression_Blend_Mode</td><td style="text-align:left;">是否启用 Live2D 的旧表情混合模式，设置为 true 或 false</td></tr><tr><td style="text-align:left;">Max_line</td><td style="text-align:left;">文本框的最大显示行数</td></tr><tr><td style="text-align:left;">Line_height</td><td style="text-align:left;">文本框的行高（单位：em）</td></tr></tbody></table><p>以下是配置文件示例：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#F8F8F2;">Game_name:WebGAL; </span></span>
<span class="line"><span style="color:#F8F8F2;">Game_key:0f33fdGr;</span></span>
<span class="line"><span style="color:#F8F8F2;">Title_img:Title.png;</span></span>
<span class="line"><span style="color:#F8F8F2;">Title_bgm:夏影.mp3;</span></span>
<span class="line"><span style="color:#F8F8F2;">Game_Logo:WebGalEnter.png|bg.png;</span></span>
<span class="line"><span style="color:#F8F8F2;">Enable_Appreciation:true;</span></span>
<span class="line"><span style="color:#F8F8F2;"></span></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="切换语言" tabindex="-1"><a class="header-anchor" href="#切换语言" aria-hidden="true">#</a> 切换语言</h2><p><code>Default_Language</code> 只用于设置玩家首次进入游戏时的默认界面语言。玩家之后仍可在游戏菜单的 <code>选项 -&gt; 系统 -&gt; Language</code> 中切换语言，所选结果会保存在本地，下次进入游戏时优先使用本地设置。</p><p>如果你同时准备了多语言剧本，需要在脚本中读取当前界面语言，并跳转到对应的场景文件。可以使用内部变量 <code>$userData.optionData.language</code>：</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">setVar</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">lang=($userData.optionData.language)</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeScene</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">start_zh.txt </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">when</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">lang==0</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeScene</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">start_en.txt </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">when</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">lang==1</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeScene</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">start_ja.txt </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">when</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">lang==2</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其中，不同数字对应的语言如下：</p><table><thead><tr><th style="text-align:left;">值</th><th style="text-align:left;">语言</th></tr></thead><tbody><tr><td style="text-align:left;">0</td><td style="text-align:left;">简体中文</td></tr><tr><td style="text-align:left;">1</td><td style="text-align:left;">English</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">日本語</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">Français</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">Deutsch</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">繁體中文</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>菜单中的语言切换会改变引擎界面语言。如果你希望游戏正文也跟随切换，需要像上面这样在脚本里自行分流到不同语言的场景。</p></div>`,12),d=[n];function i(r,o){return e(),l("div",null,d)}const g=t(s,[["render",i],["__file","config.html.vue"]]);export{g as default};
